# Use bbox around Ottawa (45.2-45.5, -75.9 to -75.4) and time filter for 2026
u = "https://api.weather.gc.ca/collections/climate-daily/items?f=json&limit=10&bbox=-75.9,45.2,-75.4,45.5&time=2026-01-01T00:00:00Z/2026-01-31T23:59:59Z"
