seen=set()
for f in d.get('features',[]):
    p=f['properties']
    key=(p.get('STN_ID'),p.get('STATION_NAME'))
    if key not in seen:
        seen.add(key)
        print(key, '|', p.get('LOCAL_DATE'), '| snow:', p.get('TOTAL_SNOW'))
EOF","description":"Query API with bbox around Ottawa to find station IDs"}

