import urllib.request, json, urllib.parse
def get(u):
    try:
        r = urllib.request.urlopen(urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'}), timeout=60)
        return r.status, r.read().decode('utf-8','replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8','replace')

# search for station name containing ORLEANS with bbox + time
for u in [
 "https://api.weather.gc.ca/collections/climate-daily/items?f=json&limit=20&bbox=-76.1,45.0,-75.3,45.6&time=2025-12-01T00:00:00Z/2025-12-31T23:59:59Z",
 "https://api.weather.gc.ca/collections/climate-daily/items?f=json&limit=20&where=" + urllib.parse.quote("STATION_NAME LIKE '%ORLEANS%'"),
]:
    s,b = get(u)
    print("==", u[:130], "->", s, len(b))
    try:
        d=json.loads(b)
        seen={}
        for f in d.get('features',[]):
            p=f['properties']
            key=(p.get('STN_ID'),p.get('STATION_NAME'))
            seen[key]=(f['geometry']['coordinates'], p.get('LOCAL_DATE'))
        for k,v in seen.items(): print(k, v)
    except Exception as e:
        print(b[:300])
EOF","description":"Search API for Orleans station by bbox and name"}

