import urllib.request, json, urllib.parse
def get(u):
    try:
        r = urllib.request.urlopen(urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'}), timeout=60)
        return r.status, r.read().decode('utf-8','replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8','replace')

# 1) try STN_ID numeric comparison (STN_ID is an integer field)
for u in [
 "https://api.weather.gc.ca/collections/climate-daily/items?f=json&limit=5&where=" + urllib.parse.quote("STN_ID=33898"),
 "https://api.weather.gc.ca/collections/climate-daily/items?f=json&limit=5&where=" + urllib.parse.quote("CLIMATE_IDENTIFIER LIKE '%OTTAWA%'"),
]:
    s,b = get(u)
    print("==", u[:120], "->", s, len(b))
    try:
        d=json.loads(b)
        for f in d.get('features',[]):
            p=f['properties']
            print(p.get('STN_ID'), '|', p.get('STATION_NAME'), '|', p.get('LOCAL_DATE'), '| snow:', p.get('TOTAL_SNOW'))
    except Exception:
        print(b[:200])
EOF","description":"Test STN_ID numeric and CLIMATE_IDENTIFIER filters"}

