import urllib.request, json, urllib.parse
def get(u):
    try:
        r = urllib.request.urlopen(urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'}), timeout=60)
        return r.status, r.read().decode('utf-8','replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8','replace')

# climate-monthly collection - query Ottawa area for 2025-12 to find station IDs and check data availability
u = "https://api.weather.gc.ca/collections/climate-monthly/items?f=json&limit=30&bbox=-76.2,45.0,-75.3,45.7"
s,b = get(u)
print(s, len(b))
d=json.loads(b)
seen={}
for f in d.get('features',[]):
    p=f['properties']
    key=(p.get('STN_ID'),p.get('STATION_NAME'))
    seen[key]=(f['geometry']['coordinates'], p.get('LOCAL_DATE'))
for k,v in sorted(seen.items(), key=lambda x: str(x[1][0])): print(k, v)
EOF","description":"Query climate-monthly collection for Ottawa stations"}

