import urllib.request, json, urllib.parse
def get(u):
    try:
        r = urllib.request.urlopen(urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'}), timeout=60)
        return r.status, r.read().decode('utf-8','replace')
    except urllib.error.HTTPError as e:
        return e.code, e.read().decode('utf-8','replace')

# climate-monthly for station 53001 (OTTAWA GATINEAU A) - get all records, check date range and fields
u = "https://api.weather.gc.ca/collections/climate-monthly/items?f=json&limit=1000&where=" + urllib.parse.quote("STN_ID=53001")
s,b = get(u)
print(s, len(b))
d=json.loads(b)
feats=d.get('features',[])
print("matched:", d.get('numberMatched'), "returned:", len(feats))
if feats:
    dates=[f['properties'].get('LOCAL_DATE') for f in feats]
    print("min:", min(dates), "max:", max(dates))
    # print last 15 months with snow fields
    feats.sort(key=lambda f: f['properties'].get('LOCAL_DATE',''))
    for f in feats[-15:]:
        p=f['properties']
        print(p.get('LOCAL_DATE'), '| snow:', p.get('TOTAL_SNOW'), '| rain:', p.get('TOTAL_RAIN'), '| precip:', p.get('TOTAL_PRECIPITATION'))
    # show all keys of first feature
    print("KEYS:", list(feats[0]['properties'].keys()))
EOF","description":"Get climate-monthly records for station 53001"}

